-- Daily challenges for 2026-11-10: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-10. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('being-a-good-teammate', 'Being a Good Teammate', 'For anyone who works, studies or volunteers alongside other people. Each day is one small way to share the load, communicate clearly, give credit, ask for help and make the group a little easier to be part of.', 'Work', 365, array['Work', 'Communication', 'Relationships']::text[], 1, '2026-11-10T17:00:00+00:00'::timestamptz),
  ('playing-games-together', 'Playing Games Together', 'For anyone who wants more laughter and connection with family, friends or neighbors. Each day is one small way to play a game together, from cards and puzzles to backyard games, and enjoy the fun more than the winning.', 'Play', 365, array['Relationships', 'Family', 'Self-Care']::text[], 1, '2026-11-10T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('being-a-good-teammate', 'playing-games-together');

